<script setup lang="ts">
import { IonContent, IonPage } from '@ionic/vue'
import { useRoute, useRouter } from 'vue-router'
import { onMounted, ref } from 'vue'
import HeaderWithReturn from '@/components/HeaderWithReturn.vue'
import { userService } from '@/services/user'
import { useFetchState } from '@/composables/useFetchState'
import UniverseList from '@/components/UniverseList.vue'
import type { SimpleUniverseResponse } from '@/types/universe'

const { params } = useRoute()
const category = `${params.category}`
const router = useRouter()

const { fetchState: fetchUniversesState } = useFetchState()
const universes = ref<SimpleUniverseResponse[]>([])

onMounted(() => {
  fetchUniverses()
})

async function fetchUniverses() {
  try {
    fetchUniversesState.value = 'waitRes'
    if (category === 'favorite') {
      universes.value = (await userService.getFavoriteUniverses()).data
    }
    else if (category === 'created') {
      universes.value = (await userService.getCreatedUniverses()).data
    }
    fetchUniversesState.value = 'success'
  }
  catch (error) {
    fetchUniversesState.value = 'failed'
    console.error(error)
  }
}

function handleChatBtnClick(universe: SimpleUniverseResponse) {
  router.push(`/sekai/${universe.universeId}`)
}
</script>

<template>
  <ion-page>
    <header-with-return :title="$t(`universesListPage.${category}`)" />
    <ion-content>
      <universe-list
        :fetch-state="fetchUniversesState"
        :universes="universes"
        @click-retry="() => { fetchUniverses() }"
        @click-chat="(universe) => { handleChatBtnClick(universe) }"
      />
    </ion-content>
  </ion-page>
</template>
